// 不使用线程池：每个任务创建新线程
for (int i = 0; i < 1000; i++) {
    new Thread(() -> {
        // 执行任务
    }).start();  // 创建1000个线程，资源浪费严重
}

// 使用线程池：复用固定数量的线程
ExecutorService pool = Executors.newFixedThreadPool(10);
for (int i = 0; i < 1000; i++) {
    pool.execute(() -> {
        // 执行任务
    });  // 只有10个线程在复用
}
pool.shutdown();
